  .object({
    lat: z.number().min(-90).max(90),
    lon: z.number().min(-180).max(180),
  })
  .refine((value) => !newcastleAxesSwapped(value.lat, value.lon), {
    message: "coordinates are swapped: expected { lat, lon }",
  });

