        <Text variant="title">{TITLE}</Text>
        {state.kind === "sensors" && state.simulated && (
          <Text variant="caption">{SAMPLE_LABEL}</Text>
        )}
        {state.kind === "loading" && <Text variant="caption">{LOADING}</Text>}
      </View>
      <SensorMap
        sensors={sensors}
        selectedId={selectedId}
        onSelect={setSelectedId}
        now={now}
        style={styles.map}
        heat={heat}
