/** A Street Manager permit already placed relative to the hotel. */
export type RoadworksInput = {
  distanceM: number;
  /** Calendar dates (YYYY-MM-DD) the permit is active. Dates outside the stay do not count. */
  activeDates: readonly string[];
  /**
